//@ts-nocheck
import * as THREE from 'three'
import { APPLY_LIGHTMAP_GLSL, DEFAULT_LIGHTMAP_PARAMS, type BlockLightmapParams } from '../../lib/blockEntityLighting'
import { FOLIAGE_SWAY_GLSL } from './foliageSwayGlsl'
import { LEGACY_SHADOW_CASTER_FRAGMENT, LEGACY_SHADOW_NORMAL_GLSL, SUN_SHADOW_FRAGMENT_GLSL, SUN_SHADOW_VERTEX_GLSL } from './sunShadowGlsl'
import { BLOCK_EMISSION_GLSL } from './blockEmissionGlsl'
import { COLOR_GRADING_GLSL } from '../colorGrading'
import { SECTION_FADE_FRAGMENT_GLSL, SECTION_FADE_VERTEX_GLSL } from './sectionFadeGlsl'

export type RenderOrigin = { x: number; y: number; z: number }

export function computeCameraRelativeUniforms(
  renderOrigin: RenderOrigin,
  x: number,
  y: number,
  z: number
): { originDelta: RenderOrigin; cameraOriginFrac: RenderOrigin } {
  const ix = Math.floor(x)
  const iy = Math.floor(y)
  const iz = Math.floor(z)
  return {
    originDelta: {
      x: renderOrigin.x - ix,
      y: renderOrigin.y - iy,
      z: renderOrigin.z - iz
    },
    cameraOriginFrac: {
      x: x - ix,
      y: y - iy,
      z: z - iz
    }
  }
}

const vertexShader = /* glsl */ `
precision highp float;

uniform vec3 u_originDelta;
uniform vec3 u_cameraOriginFrac;

in float a_skyLight;
in float a_blockLight;

// position, uv, color: declared by Three.js shader chunks (vertexColors → USE_COLOR).
out vec3 vColor;
out vec2 v_uv;
out float v_skyLight;
out float v_blockLight;

#ifdef USE_LOGARITHMIC_DEPTH_BUFFER
out float vFragDepth;
#endif

#ifdef USE_FOG
out float vFogDepth;
#endif

${FOLIAGE_SWAY_GLSL}
${SUN_SHADOW_VERTEX_GLSL}
${SECTION_FADE_VERTEX_GLSL}
#ifdef SUN_SHADOWS
out vec3 v_legacyRelPos;
#endif

void main() {
    vec3 relativePos = modelMatrix[3].xyz + u_originDelta + position - u_cameraOriginFrac;
#ifdef WAVING_FOLIAGE_LEGACY
    relativePos += foliageSwayOffset(uv, relativePos);
#endif
#ifdef SHADOW_CASTER
    v_uv = uv;
    gl_Position = u_lightViewProj * vec4(shadowSpacePos(relativePos), 1.0);
    return;
#endif
    vec4 mvPosition = viewMatrix * vec4(relativePos, 1.0);
    gl_Position = projectionMatrix * mvPosition;
#ifdef SUN_SHADOWS
    writeSunShadowVaryings(relativePos, vec3(0.0));
    v_legacyRelPos = relativePos;
#endif
#ifdef SECTION_FADE
    v_sectionFade = sectionFadeVisibility(sectionFadeSectionOf(modelMatrix[3].xyz), relativePos.xz - position.xz);
#ifdef SECTION_FADE_SCIFI
    v_sectionFadeLocal = modelMatrix[3].xyz + position + u_sectionFadeOriginRem;
#endif
#endif

    vColor = color;
    v_uv = uv;
    v_skyLight = a_skyLight;
    v_blockLight = a_blockLight;

#ifdef USE_LOGARITHMIC_DEPTH_BUFFER
    vFragDepth = 1.0 + gl_Position.w;
#endif

#ifdef USE_FOG
    vFogDepth = -mvPosition.z;
#endif
}
`

const fragmentShader = /* glsl */ `
precision highp float;

uniform sampler2D u_atlas;
uniform float u_skyLevel;
uniform float u_lightCurve;
uniform float u_minBrightness;
uniform float u_lightGamma;

in vec3 vColor;
in vec2 v_uv;
in float v_skyLight;
in float v_blockLight;

#ifdef USE_LOGARITHMIC_DEPTH_BUFFER
uniform float logDepthBufFC;
in float vFragDepth;
#endif

#ifdef USE_FOG
uniform vec3 fogColor;
in float vFogDepth;
#ifdef FOG_EXP2
uniform float fogDensity;
#else
uniform float fogNear;
uniform float fogFar;
#endif
#endif

out vec4 FragColor;

void writeLogDepth() {
#ifdef USE_LOGARITHMIC_DEPTH_BUFFER
    gl_FragDepth = log2(vFragDepth) * logDepthBufFC * 0.5;
#endif
}

void applyFog() {
#ifdef USE_FOG
#ifdef FOG_EXP2
    float fogFactor = 1.0 - exp(-fogDensity * fogDensity * vFogDepth * vFogDepth);
#else
    float fogFactor = smoothstep(fogNear, fogFar, vFogDepth);
#endif
    FragColor.rgb = mix(FragColor.rgb, fogColor, fogFactor);
#endif
}

${APPLY_LIGHTMAP_GLSL}
${SUN_SHADOW_FRAGMENT_GLSL}
${SECTION_FADE_FRAGMENT_GLSL}
${LEGACY_SHADOW_NORMAL_GLSL}
${BLOCK_EMISSION_GLSL}
${COLOR_GRADING_GLSL}

void main() {
    vec4 texColor = texture(u_atlas, v_uv);
    float sky = min(v_skyLight, u_skyLevel);
#ifdef SUN_SHADOWS
    sky = legacyShadowedSkyLight(sky);
#endif
    float L = max(v_blockLight, sky);
    float Lm = applyLightmap(L);
    vec3 rgb = texColor.rgb * vColor * Lm;
    float alpha = texColor.a;

    if (alpha < 0.1) {
        discard;
    }

    FragColor = vec4(rgb, alpha);
#ifdef BLOCK_EMISSION
    FragColor.a = blockEmissionAlpha(ivec2(floor(v_uv * vec2(textureSize(u_atlas, 0)) / 16.0)), texColor.rgb * vColor);
#endif
#ifdef BLOCK_GRADING
    FragColor.rgb = colorGrade(FragColor.rgb);
#endif
#ifdef SECTION_FADE
    applySectionFade(FragColor);
#endif
    applyFog();
    writeLogDepth();
}
`

const globalVertexShader = /* glsl */ `
precision highp float;

uniform vec3 u_originDelta;
uniform vec3 u_cameraOriginFrac;

in vec3 a_origin;
in float a_skyLight;
in float a_blockLight;

// position, uv, color: declared by Three.js shader chunks (vertexColors → USE_COLOR).
out vec3 vColor;
out vec2 v_uv;
out float v_skyLight;
out float v_blockLight;

#ifdef USE_LOGARITHMIC_DEPTH_BUFFER
out float vFragDepth;
#endif

#ifdef USE_FOG
out float vFogDepth;
#endif

${FOLIAGE_SWAY_GLSL}
${SUN_SHADOW_VERTEX_GLSL}
${SECTION_FADE_VERTEX_GLSL}
#ifdef SUN_SHADOWS
out vec3 v_legacyRelPos;
#endif

void main() {
    vec3 relativePos = a_origin + u_originDelta + position - u_cameraOriginFrac;
#ifdef WAVING_FOLIAGE_LEGACY
    relativePos += foliageSwayOffset(uv, relativePos);
#endif
#ifdef SHADOW_CASTER
    v_uv = uv;
    gl_Position = u_lightViewProj * vec4(shadowSpacePos(relativePos), 1.0);
    return;
#endif
    vec4 mvPosition = viewMatrix * vec4(relativePos, 1.0);
    gl_Position = projectionMatrix * mvPosition;
#ifdef SUN_SHADOWS
    writeSunShadowVaryings(relativePos, vec3(0.0));
    v_legacyRelPos = relativePos;
#endif
#ifdef SECTION_FADE
    v_sectionFade = sectionFadeVisibility(sectionFadeSectionOf(a_origin), relativePos.xz - position.xz);
#ifdef SECTION_FADE_SCIFI
    v_sectionFadeLocal = a_origin + position + u_sectionFadeOriginRem;
#endif
#endif

    vColor = color;
    v_uv = uv;
    v_skyLight = a_skyLight;
    v_blockLight = a_blockLight;

#ifdef USE_LOGARITHMIC_DEPTH_BUFFER
    vFragDepth = 1.0 + gl_Position.w;
#endif

#ifdef USE_FOG
    vFogDepth = -mvPosition.z;
#endif
}
`

const legacyUniforms = {
  u_atlas: { value: null },
  u_originDelta: { value: new THREE.Vector3() },
  u_cameraOriginFrac: { value: new THREE.Vector3() },
  u_skyLevel: { value: 1.0 },
  u_lightCurve: { value: DEFAULT_LIGHTMAP_PARAMS.curve },
  u_minBrightness: { value: DEFAULT_LIGHTMAP_PARAMS.minBrightness },
  u_lightGamma: { value: DEFAULT_LIGHTMAP_PARAMS.gamma }
}

export function createLegacyBlockMaterial(): THREE.ShaderMaterial {
  return new THREE.ShaderMaterial({
    vertexShader,
    fragmentShader,
    uniforms: THREE.UniformsUtils.merge([THREE.UniformsLib.fog, legacyUniforms]),
    transparent: true,
    depthWrite: true,
    depthTest: true,
    vertexColors: true,
    glslVersion: THREE.GLSL3,
    fog: true
  })
}

/** Global opaque legacy buffer — per-vertex section origin via a_origin. */
export function createGlobalLegacyBlockMaterial(): THREE.ShaderMaterial {
  return new THREE.ShaderMaterial({
    vertexShader: globalVertexShader,
    fragmentShader,
    uniforms: THREE.UniformsUtils.merge([THREE.UniformsLib.fog, legacyUniforms]),
    transparent: false,
    depthWrite: true,
    depthTest: true,
    vertexColors: true,
    glslVersion: THREE.GLSL3,
    fog: true
  })
}

/** Global transparent blend buffer — same shaders as opaque global, blend material flags. */
export function createGlobalLegacyBlendMaterial(): THREE.ShaderMaterial {
  return new THREE.ShaderMaterial({
    vertexShader: globalVertexShader,
    fragmentShader,
    uniforms: THREE.UniformsUtils.merge([THREE.UniformsLib.fog, legacyUniforms]),
    transparent: true,
    depthWrite: false,
    depthTest: true,
    vertexColors: true,
    glslVersion: THREE.GLSL3,
    fog: true
  })
}

/** Depth-only variant of the global opaque legacy material for the sun shadow pass (see createCubeShadowCasterMaterial). */
export function createGlobalLegacyShadowCasterMaterial(source: THREE.ShaderMaterial, lightViewProj: { value: THREE.Matrix4 }): THREE.ShaderMaterial {
  return new THREE.ShaderMaterial({
    vertexShader: globalVertexShader,
    fragmentShader: LEGACY_SHADOW_CASTER_FRAGMENT,
    uniforms: {
      u_atlas: source.uniforms.u_atlas!,
      u_originDelta: source.uniforms.u_originDelta!,
      u_cameraOriginFrac: source.uniforms.u_cameraOriginFrac!,
      u_lightViewProj: lightViewProj
    },
    defines: { SHADOW_CASTER: '' },
    side: THREE.DoubleSide,
    blending: THREE.NoBlending,
    vertexColors: true,
    glslVersion: THREE.GLSL3,
    fog: false
  })
}

/** Render-origin + fractional camera split — matches GlobalBlockBuffer.setCameraOrigin. */
export function setLegacyCameraOrigin(material: THREE.ShaderMaterial, renderOrigin: RenderOrigin, x: number, y: number, z: number): void {
  const { originDelta, cameraOriginFrac } = computeCameraRelativeUniforms(renderOrigin, x, y, z)
  const u = material.uniforms.u_originDelta
  if (u?.value?.set) {
    u.value.set(originDelta.x, originDelta.y, originDelta.z)
  }
  const uf = material.uniforms.u_cameraOriginFrac
  if (uf?.value?.set) {
    uf.value.set(cameraOriginFrac.x, cameraOriginFrac.y, cameraOriginFrac.z)
  }
}

export function setLegacySkyLevel(material: THREE.ShaderMaterial, value: number): void {
  const u = material.uniforms.u_skyLevel
  if (u) u.value = value
}

export function setLegacyLightmapParams(material: THREE.ShaderMaterial, params: BlockLightmapParams): void {
  if (params.curve !== undefined) {
    const u = material.uniforms.u_lightCurve
    if (u) u.value = params.curve
  }
  if (params.minBrightness !== undefined) {
    const u = material.uniforms.u_minBrightness
    if (u) u.value = params.minBrightness
  }
  if (params.gamma !== undefined) {
    const u = material.uniforms.u_lightGamma
    if (u) u.value = params.gamma
  }
}
